#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d", &n);
    vector<int> p(n);
    for(int i = 0; i < n; i++) scanf("%d", &p[i]);

    vector<pair<int,int>> ops;

    auto apply = [&](int x, int y){
        vector<int> res(n);
        // suffix y elements go first
        for(int i = 0; i < y; i++) res[i] = p[n-y+i];
        // middle elements
        int mid = n - x - y;
        for(int i = 0; i < mid; i++) res[y+i] = p[x+i];
        // prefix x elements go last
        for(int i = 0; i < x; i++) res[y+mid+i] = p[i];
        p = res;
        ops.push_back({x, y});
    };

    for(int i = 0; i < n-1; i++){
        int j = -1;
        for(int k = i; k < n; k++) if(p[k] == i+1){ j = k; break; }
        if(j == i) continue;

        // Step 1: Move p[j] to position n-1
        if(j != n-1){
            // We want to put element at position j to position n-1
            // Use x = j+1, y = n-1-j. Then x+y = n, but we need x+y <= n. 
            // If x+y = n, middle is empty, that should be fine if allowed.
            // Result: [suffix(n-1-j), prefix(j+1)] => element at p[j] goes to position n-1
            int x = j+1, y = n-1-j;
            if(x >= 1 && y >= 1 && x+y <= n){
                apply(x, y);
            }
            // Now element should be at position n-1
        }

        // Step 2: Move from position n-1 to position i
        // Use x = i, y = 1 (if i >= 1): result = [p[n-1], p[i..n-2], p[0..i-1]]
        // Element goes to position 0... but we want position i.
        // Use x = n-1-i, y = 1: result = [p[n-1], p[n-1-i..n-2], p[0..n-2-i]]
        // Element at pos 0, rest shifted. Hmm.
        // Better: if remaining length is n-i, use x appropriate.
        // x=i, y=1, x+y=i+1<=n. Result: [p[n-1], p[i]...p[n-2], p[0]...p[i-1]]
        // Element at pos 0, but positions 0..i-1 were sorted and now they're at end. Bad.
        // Instead: y = n-i, x = 1 => but need i>=1. No wait...
        // x=1, y=n-1-i: [p[n-1-i..n-1], p[1..i], p[0]]. Element p[n-1] goes to position i. Yes!
        if(n-1-i >= 1 && 1 + (n-1-i) <= n){
            apply(1, n-1-i);
        }
    }

    printf("%d\n", (int)ops.size());
    for(auto&[a,b]:ops) printf("%d %d\n", a, b);
}
